// OnAlarmEventCallbackHandler returns the http.Handler for the onAlarmEvent callback.
// Mount this at the URL path advertised to callback senders. errHandler
// may be nil; if so, parameter-binding errors return 400 with the error
// message. Middlewares are applied in the order provided -- the last
// argument becomes the outermost wrapper.
func OnAlarmEventCallbackHandler(si CallbackReceiverInterface, errHandler func(w http.ResponseWriter, r *http.Request, err error), middlewares ...CallbackReceiverMiddlewareFunc) http.Handler {
	if errHandler == nil {
		errHandler = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	var h http.Handler = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		si.HandleOnAlarmEventCallback(w, r)
	})
	for _, mw := range middlewares {
		h = mw(h)
	}
	return h
}

